TEXTBOOK.vocab(1, [
  ["Paleolithic", "The Old Stone Age, before agriculture, when humans lived as mobile foragers using stone tools."],
  ["Neolithic", "The New Stone Age, marked by farming, domesticated animals, polished stone tools, and settled villages."],
  ["Neolithic Revolution", "The shift from foraging to agriculture and herding that began around 10,000 B.C.E."],
  ["Foraging", "Getting food by hunting, fishing, and gathering wild plants rather than farming."],
  ["Domestication", "The process of breeding plants and animals over generations to make them useful to humans."],
  ["Pastoralism", "A way of life based on herding domesticated animals, often moving seasonally to find pasture."],
  ["Hominin", "Humans and their extinct close relatives, such as Australopithecus and Homo erectus."],
  ["Homo sapiens", "The species of modern humans, which evolved in Africa about 300,000 years ago."],
  ["Out of Africa", "The model that modern humans originated in Africa and later migrated to the rest of the world."],
  ["Beringia", "The Ice Age land bridge connecting Siberia and Alaska, used by early migrants to the Americas."],
  ["Ice Age", "A long cold period when glaciers covered much of the world and sea levels were lower; the last ended about 12,000 years ago."],
  ["Fertile Crescent", "The arc of land in Southwest Asia where wheat, barley, sheep, and goats were first domesticated."],
  ["Çatalhüyük", "A large Neolithic town in Anatolia (c. 7100–5700 B.C.E.) known for mud-brick houses and little sign of hierarchy."],
  ["Jericho", "An early Neolithic settlement in the Jordan Valley with a stone wall and tower by about 8000 B.C.E."],
  ["Natufians", "Settled foragers in the Levant who harvested wild grain before farming began."],
  ["Megalith", "A large stone used to build monuments such as Stonehenge."],
  ["Secondary products", "Uses of live animals, such as milk, wool, and pulling plows, beyond meat."],
  ["Bronze", "An alloy of copper and tin used for tools and weapons."],
  ["Radiocarbon dating", "A method that dates once-living material by measuring the decay of carbon-14."],
  ["Archaeology", "The study of the human past through material remains such as tools, buildings, and bones."],
  ["Chiefdom", "A society led by a chief with authority over several communities, often based on control of resources."],
  ["Teosinte", "The wild Mexican grass from which maize was domesticated."],
  ["Sedentary", "Living permanently in one place rather than moving seasonally."],
  ["Surplus", "Food or goods beyond what is needed for survival, which can support specialists and trade."],
  ["Specialization of labor", "When people perform particular jobs, such as potter or priest, instead of all producing food."],
  ["Zoonotic disease", "A disease that passes from animals to humans, such as smallpox and influenza."],
  ["Ötzi", "A man preserved in Alpine ice who died around 3300 B.C.E., carrying a copper axe and other tools."],
  ["Clovis points", "Fluted stone spear points used by hunters in North America about 13,000 years ago."],
]);
